{
  "name": "cliproxy-image-mcp",
  "version": "0.1.0",
  "description": "Cross-platform MCP server for CLIProxyAPI GPT Image endpoints, with OpenCode installer",
  "type": "module",
  "bin": {
    "cliproxy-image-mcp": "bin/cli.js"
  },
  "files": [
    "bin",
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "start": "node bin/cli.js",
    "check": "node --check bin/cli.js && node --check src/server.js && node --check src/install.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "mcp",
    "opencode",
    "cliproxyapi",
    "gpt-image"
  ],
  "license": "MIT",
  "dependencies": {
    "@modelcontextprotocol/server": "2.0.0",
    "jsonc-parser": "3.3.1",
    "zod": "4.5.4"
  }
}
